-- Pure logic of game_killdissolve (client/MANIFEST.md "game_killdissolve", O563): which kill effect plays how, the cap of
-- simultaneous dissolves, the timing and the outfit that carries the shader numbers. No engine call here
-- (killdissolve_core_test.lua runs it with plain Lua).
--
-- A dissolve kill effect (server cosmetics_config.lua `dissolve` / `tint`) is the dying monster's own sprite drawn by an
-- outfit shader (data/shaders/chaos_outfit_kd_<mode>.frag, generated by client/tools/gen_kill_dissolve.py) while the
-- shader's progress goes from 0 to 1. The shader numbers travel in the outfit table as shaderA .. shaderD (base patch
-- 0201): A = progress, B = tint + 1, C = seed, D = the part's width in sprite pixels.
KillDissolveCore = {}
local K = KillDissolveCore

-- the seven modes: how long the dissolve plays (ms) and the shader it uses; the order is the generator's
K.ORDER = { 'sand', 'pixels', 'ash', 'burn', 'void', 'frost', 'gold' }
K.MODES = {
  sand = { ms = 1000 }, pixels = { ms = 1000 }, ash = { ms = 1100 }, burn = { ms = 1000 }, void = { ms = 1100 },
  frost = { ms = 1100 }, gold = { ms = 1100 },
}
K.SHADER_PREFIX = 'chaos_kd_'                   -- the registered outfit shader name: chaos_kd_<mode>
K.FILE_PREFIX = '/shaders/chaos_outfit_kd_'      -- the fragment stage file: <prefix><mode>
K.VERTEX = '/shaders/chaos_outfit_vertex'
K.FRAME_MS = 33                                  -- one outfit update every 33 ms (30 per second)
K.MAX_ACTIVE = 6                                 -- dissolves running at once on a desktop; more kills play the plain effect
K.MAX_ACTIVE_MOBILE = 3
K.TINTS = 8                                      -- tint 0 .. 7 (the shader's palette)
K.MIN_PROGRESS = 0.001                           -- the shader numbers are never all 0 (the engine skips an all-0 set)

local function num(v, d)
  v = tonumber(v)
  if v == nil or v ~= v or v == math.huge or v == -math.huge then return d end
  return v
end

local function clamp(v, lo, hi)
  if v < lo then return lo end
  if v > hi then return hi end
  return v
end

function K.isMode(mode)
  return type(mode) == 'string' and K.MODES[mode] ~= nil
end

function K.shaderName(mode)
  return K.isMode(mode) and (K.SHADER_PREFIX .. mode) or nil
end

function K.duration(mode)
  return K.isMode(mode) and K.MODES[mode].ms or 0
end

-- 0 .. 1 over the dissolve, linear (the shader shapes it); never below MIN_PROGRESS while it plays
function K.progress(mode, elapsedMs)
  local ms = K.duration(mode)
  if ms <= 0 then return 1 end
  return clamp(num(elapsedMs, 0) / ms, K.MIN_PROGRESS, 1)
end

-- a seed 0 .. 1 from the place of the kill (every dissolve of the same monster look a little different)
function K.seedOf(x, y, z, id)
  local n = (num(x, 0) * 73856093 + num(y, 0) * 19349663 + num(z, 0) * 83492791 + num(id, 0) * 2654435761) % 1000003
  return (n % 997) / 996
end

-- the outfit of a dissolve frame: a copy of `base` ({type, head, body, legs, feet, addons}) with the shader and its numbers
function K.outfitFor(base, mode, tint, progress, seed, width)
  if type(base) ~= 'table' or not K.isMode(mode) then return nil end
  local o = {}
  for k, v in pairs(base) do o[k] = v end
  o.shader = K.shaderName(mode)
  o.shaderA = clamp(num(progress, K.MIN_PROGRESS), K.MIN_PROGRESS, 1)
  o.shaderB = clamp(math.floor(num(tint, 0)), 0, K.TINTS - 1) + 1
  o.shaderC = clamp(num(seed, 0), 0, 1)
  o.shaderD = math.max(8, math.floor(num(width, 32)))
  return o
end

-- the monster look of a message: {type = lookType, head, body, legs, feet, addons: 0 .. 3}, nil when it is no creature look
function K.sanitizeLook(o)
  if type(o) ~= 'table' then return nil end
  local t = math.floor(num(o.l, 0))
  if t <= 0 or t > 65535 then return nil end
  local function col(v) return clamp(math.floor(num(v, 0)), 0, 132) end
  return { type = t, head = col(o.h), body = col(o.b), legs = col(o.g), feet = col(o.f),
    addons = clamp(math.floor(num(o.a, 0)), 0, 3) }
end

-- a place of the map from a message
function K.sanitizePos(m)
  if type(m) ~= 'table' then return nil end
  local x, y, z = math.floor(num(m.x, 0)), math.floor(num(m.y, 0)), math.floor(num(m.z, -1))
  if x <= 0 or y <= 0 or z < 0 or z > 15 then return nil end
  return { x = x, y = y, z = z }
end

-- the plain effect a message names (the server's own kill effect: id and the tile shift), nil when none
function K.plainEffect(m)
  local v = type(m) == 'table' and m.v
  if type(v) ~= 'table' then return nil end
  local id = math.floor(num(v.id, 0))
  if id <= 0 then return nil end
  return { id = id, dx = math.floor(num(v.dx, 0)), dy = math.floor(num(v.dy, 0)) }
end

-- ---------------------------------------------------------------- the cap
function K.newCap(max)
  return { active = 0, max = math.max(0, math.floor(num(max, K.MAX_ACTIVE))), dropped = 0, started = 0 }
end

function K.admit(cap)
  if cap.active >= cap.max then
    cap.dropped = cap.dropped + 1
    return false
  end
  cap.active = cap.active + 1
  cap.started = cap.started + 1
  return true
end

function K.release(cap)
  if cap.active > 0 then cap.active = cap.active - 1 end
end

-- ---------------------------------------------------------------- the decision
-- msg = the server's {m = mode, t = tint, i = creature id, x, y, z, o = look, v = plain effect}
-- env = {enabled = the option, hasParams = Creature.hasShaderParams() (base patch 0201), ready = function(mode) -> the
--        shader is registered, cap = K.newCap}
-- -> {action = 'dissolve', mode, tint, seed, look, pos} | {action = 'plain', effect, pos, why} | {action = 'none'}
function K.plan(msg, env)
  if type(msg) ~= 'table' or type(env) ~= 'table' then return { action = 'none' } end
  local pos = K.sanitizePos(msg)
  if not pos then return { action = 'none' } end
  local plain = K.plainEffect(msg)
  local function fallback(why)
    if plain then return { action = 'plain', effect = plain, pos = pos, why = why } end
    return { action = 'none', why = why }
  end
  if not K.isMode(msg.m) then return fallback('mode') end
  local look = K.sanitizeLook(msg.o)
  if not look then return fallback('look') end
  if env.enabled == false then return fallback('off') end
  if not env.hasParams then return fallback('engine') end
  if type(env.ready) == 'function' and not env.ready(msg.m) then return fallback('shader') end
  if not env.cap or not K.admit(env.cap) then return fallback('cap') end
  local tint = clamp(math.floor(num(msg.t, 0)), 0, K.TINTS - 1)
  return { action = 'dissolve', mode = msg.m, tint = tint, seed = K.seedOf(pos.x, pos.y, pos.z, msg.i),
    look = look, pos = pos, direction = clamp(math.floor(num(msg.d, 2)), 0, 7) }
end

-- ---------------------------------------------------------------- the preview loop of the Customise window
-- the monster stands, dissolves, is gone for a moment and stands again
K.STAND_MS = 700
K.GONE_MS = 450
K.APPEAR_MS = 250

function K.loopMs(mode)
  return K.STAND_MS + K.duration(mode) + K.GONE_MS + K.APPEAR_MS
end

-- the phase `ms` into the loop: {phase = 'stand' | 'dissolve' | 'gone' | 'appear', progress (dissolve), alpha (appear)}
function K.stage(mode, ms)
  local total = K.loopMs(mode)
  if total <= 0 then return { phase = 'stand' } end
  local t = num(ms, 0) % total
  if t < K.STAND_MS then return { phase = 'stand' } end
  t = t - K.STAND_MS
  local d = K.duration(mode)
  if t < d then return { phase = 'dissolve', progress = K.progress(mode, t) } end
  t = t - d
  if t < K.GONE_MS then return { phase = 'gone' } end
  t = t - K.GONE_MS
  return { phase = 'appear', alpha = clamp(t / K.APPEAR_MS, 0, 1) }
end

-- the number of 33 ms updates the preview of one tile makes per second while it animates (0 = none)
function K.tileFps(hovered, selected)
  if hovered or selected then return math.floor(1000 / K.FRAME_MS) end
  return 0
end

return K
